1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { PageHeader, EmptyState } from "@/components/ui/primitives";
5	import { DeployWizard } from "@/components/customer/DeployWizard";
6	import { capacitySnapshot } from "@/lib/capacity";
7	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
8	import { extraDiskPerGbCents } from "@/lib/disk-expand";
9	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
10	import { currentPromo } from "@/lib/promotions";
11	import { firstMonthFreeAppliesTo, firstMonthFreeEnabled } from "@/lib/promo-redemption";
12	import { annualDiscountPct } from "@/lib/annual-discount";
13	import { taxContextForUser } from "@/lib/tax";
14	import { defaultTermMonths, getSetting } from "@/lib/settings";
15	
16	export const dynamic = "force-dynamic";
17	
18	export default async function DeployPage() {
19	  const user = await requireUser();
20	  // The active intro promo (Summer Sale etc.). payAndDeploy charges the promo
21	  // price on the first term (lib/order.ts), so the wizard must DISPLAY it too —
22	  // otherwise displayed ($8.99) ≠ charged ($6.29). Computed server-side so the
23	  // shown promo matches the one checkout applies.
24	  const promo = currentPromo(new Date());
25	  // BUT the current promo is FIRST-MONTH-FREE, which is scoped to Shared Hosting ONLY —
26	  // a VPS order always bills full price (lib/order.ts orderQuote gates the CHARGE on
27	  // `firstMonthFreeAppliesTo("VPS")`, which is false). This is the VPS deploy wizard, so
28	  // we must gate the DISPLAY the exact same way, or the wizard shows "$0 first month"
29	  // while checkout charges $8.99 — displayed ≠ charged, the wrong direction. A future
30	  // non-first-month-free promo (a real VPS sale) would still surface here.
31	  const vpsPromoApplies = promo.firstMonthFree
32	    ? firstMonthFreeAppliesTo("VPS") && (await firstMonthFreeEnabled())
33	    : promo.discountPercent > 0;
34	  const vpsPromoPercent = vpsPromoApplies ? promo.discountPercent : 0;
35	  const vpsPromoLabel = vpsPromoApplies ? promo.label : undefined;
36	  // VAT/GST for this customer's billing country (Finding 1). 0 unless they have a
37	  // country on file, so the wizard total is unchanged for everyone else.
38	  const taxCtx = await taxContextForUser(user);
39	  const [plans, images, sshKeys, nodes, capacity, freeIps, defaultPlanSlug, defaultTerm] =
40	    await Promise.all([
41	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
42	      db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
43	      db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
44	      db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
45	      capacitySnapshot(),
46	      db.dedicatedIp.count({ where: { status: "FREE" } }),
47	      // Settings → Provisioning, "Default plan". Stored as a slug; resolved to an id
48	      // below because the wizard selects by id.
49	      getSetting("default_plan_slug", ""),
50	      // Settings → Billing, "Default billing term", in months and pre-validated against
51	      // VPS_TERMS.
52	      defaultTermMonths(),
53	    ]);
54	
55	  // Resolve slug → id HERE, against the same `plans` array handed to the wizard, so the
56	  // pre-selection can only ever name a plan the customer can actually see and buy. A
57	  // slug that no longer resolves (plan renamed, or deactivated since an operator chose
58	  // it) yields `undefined` and the wizard keeps its "first plan by sortOrder" default —
59	  // the panel's promise degrades to the old behaviour instead of pre-selecting nothing.
60	  const defaultPlanId = defaultPlanSlug
61	    ? plans.find((p) => p.slug === defaultPlanSlug)?.id
62	    : undefined;
63	
64	  return (
65	    <div className="space-y-6">
66	      <PageHeader title="Deploy" sub="Choose what to launch — a VPS, a shared-hosting site, or a game server." />
67	
68	      {/* Product chooser: VPS is configured on this page (wizard below); Shared
69	          Hosting and Game Servers have their own flows. */}
70	      <div className="grid gap-3 sm:grid-cols-3">
71	        <div className="card border-brand-500/40 bg-brand-500/[0.06]">
72	          <div className="text-sm font-semibold text-white">VPS Hosting</div>
73	          <p className="mt-1 text-xs text-slate-400">Full-root NVMe KVM server — configure it below.</p>
74	        </div>
75	        <Link href="/dashboard/hosting" className="card lift hover:border-white/15">
76	          <div className="text-sm font-semibold text-white">Shared Hosting →</div>
77	          <p className="mt-1 text-xs text-slate-400">One-click WordPress &amp; sites, no server to manage.</p>
78	        </Link>
79	        <Link href="/dashboard/games" className="card lift hover:border-white/15">
80	          <div className="text-sm font-semibold text-white">Game Server →</div>
81	          <p className="mt-1 text-xs text-slate-400">Minecraft, Rust, Valheim, Palworld &amp; more.</p>
82	        </Link>
83	      </div>
84	      {capacity.nearCapacity && (
85	        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
86	          <span className="font-semibold">Host is filling up.</span> We&apos;re at{" "}
87	          {Math.round(capacity.ramUtilization * 100)}% of committed RAM. Larger plans may be briefly unavailable.
88	        </div>
89	      )}
90	      {plans.length === 0 || images.length === 0 ? (
91	        <EmptyState
92	          title="Deployments are temporarily unavailable"
93	          sub="No active plans or images are configured. Please check back soon or contact support."
94	        />
95	      ) : (
96	        <DeployWizard
97	          plans={plans.map((p) => ({
98	            id: p.id,
99	            name: p.name,
100	            cpuCores: p.cpuCores,
101	            ramMB: p.ramMB,
102	            diskGB: p.diskGB,
103	            bandwidthTB: p.bandwidthTB,
104	            priceCents: p.priceCents,
105	            storageTier: p.storageTier,
106	          }))}
107	          images={images.map((o) => ({
108	            id: o.id,
109	            slug: o.slug,
110	            name: o.name,
111	            category: o.category,
112	            family: o.family,
113	            version: o.version,
114	            logo: o.logo,
115	            minRamMB: o.minRamMB,
116	            minDiskGB: o.minDiskGB,
117	            licenseRequired: o.licenseRequired,
118	            featured: o.featured,
119	          }))}
120	          nodes={nodes}
121	          sshKeys={sshKeys.map((k) => ({ id: k.id, name: k.name }))}
122	          isAdmin={user.role === "ADMIN"}
123	          balanceCents={user.balanceCents}
124	          dedicatedIpAvailable={freeIps > 0}
125	          dedicatedIpPriceCents={await dedicatedIpMonthlyCents()}
126	          extraDiskPriceCentsPerGb={await extraDiskPerGbCents()}
127	          backupPlusPriceCents={await backupPlusMonthlyCents()}
128	          defaultPlanId={defaultPlanId}
129	          defaultTermMonths={defaultTerm}
130	          promoPercent={vpsPromoPercent}
131	          promoLabel={vpsPromoLabel}
132	          annualDiscountPct={await annualDiscountPct()}
133	          taxRatePercent={taxCtx.ratePercent}
134	          taxCountry={taxCtx.country}
135	        />
136	      )}
137	    </div>
138	  );
139	}
