1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { listHostingAccounts } from "@/lib/actions-hosting";
4	import { annualDiscountPct } from "@/lib/annual-discount";
5	import { firstMonthFreeAppliesTo, firstMonthFreeEnabled, firstMonthFreeEligible } from "@/lib/promo-redemption";
6	import { clientIp } from "@/lib/rate-limit";
7	import { hashIp } from "@/lib/coupon-order";
8	import { headers } from "next/headers";
9	import { hostingAppCatalog } from "@/worker/hosting";
10	import { HOSTING_SUBDOMAIN_BASE } from "@/lib/hosting";
11	import { hasChargeableCard, cardDisplayLabel } from "@/lib/stripe-cards";
12	import { stripeConfigured } from "@/lib/stripe";
13	import { HostingClient } from "@/components/customer/HostingClient";
14	
15	export const dynamic = "force-dynamic";
16	
17	export default async function HostingPage() {
18	  const user = await requireUser();
19	  // The first-month-free promo is HOSTING-ONLY (firstMonthFreeAppliesTo) and only
20	  // when the owner toggle is on. Resolved server-side so the order UI advertises the
21	  // promo only when checkout will actually grant it — displayed === charged.
22	  const [plans, accounts, annualPct, promoOn] = await Promise.all([
23	    db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
24	    listHostingAccounts(),
25	    annualDiscountPct(),
26	    firstMonthFreeAppliesTo("HOSTING") ? firstMonthFreeEnabled() : Promise.resolve(false),
27	  ]);
28	  // Advertise the free-month promo ONLY when THIS user is actually eligible — the same
29	  // predicate (by userId AND ipHash) that orderHostingAccount charges on. Without this,
30	  // a repeat customer or someone on a shared IP that already redeemed sees "$0 today"
31	  // but is silently debited the full price (displayed ≠ charged). Money-audit fix.
32	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
33	  const firstMonthFree = promoOn && (await firstMonthFreeEligible(user.id, ipHash));
34	  const planViews = plans.map((p) => ({
35	    id: p.id,
36	    name: p.name,
37	    priceCents: p.priceCents,
38	    diskGB: p.diskGB,
39	    maxSites: p.maxSites,
40	    maxDatabases: p.maxDatabases,
41	    bandwidthTB: p.bandwidthTB,
42	    mailboxes: p.mailboxes,
43	    freeMigration: p.freeMigration,
44	    featured: p.featured,
45	    tagline: p.tagline,
46	  }));
47	  const apps = hostingAppCatalog();
48	  const hasCard = hasChargeableCard(user);
49	  const cardLabel = hasCard
50	    ? cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear })
51	    : null;
52	  return (
53	    <HostingClient
54	      plans={planViews}
55	      accounts={accounts}
56	      apps={apps}
57	      annualDiscountPct={annualPct}
58	      firstMonthFree={firstMonthFree}
59	      balanceCents={user.balanceCents}
60	      hasCard={hasCard}
61	      cardLabel={cardLabel}
62	      stripeReady={stripeConfigured()}
63	      tempSubdomainBase={HOSTING_SUBDOMAIN_BASE}
64	    />
65	  );
66	}
