3	import { useState } from "react";
4	import Link from "next/link";
5	import { retryHostingProvision, type HostingAccountView } from "@/lib/actions-hosting";
6	import { Badge, EmptyState, StatusDot } from "@/components/ui/primitives";
7	import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
8	import { HostingDeployWizard, type WizardPlan } from "@/components/customer/HostingDeployWizard";
9	
10	export function HostingClient({
11	  plans,
12	  accounts,
13	  apps,
14	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
15	  firstMonthFree = false,
16	  balanceCents,
17	  hasCard,
18	  cardLabel,
19	  stripeReady,
20	  tempSubdomainBase,
21	}: {
22	  plans: WizardPlan[];
23	  accounts: HostingAccountView[];
24	  apps: { slug: string; name: string; needsDb: boolean }[];
25	  /** Live admin annual discount (%), so the Annual term shows the REAL price/savings. */
26	  annualDiscountPct?: number;
27	  /**
28	   * Is the first-month-free promo live for shared hosting? Resolved server-side
29	   * (firstMonthFreeAppliesTo("HOSTING") + owner toggle) so the "FREE first month"
30	   * copy shows ONLY when checkout will actually grant it. Display only — the charge
31	   * logic lives in orderHostingAccount; nothing here alters what is billed.
32	   */
33	  firstMonthFree?: boolean;
34	  /** The customer's wallet balance (renewal-source + gate math). */
35	  balanceCents: number;
36	  /** A renewal-capable card is on file (billed off-session at renewal). */
37	  hasCard: boolean;
38	  cardLabel: string | null;
39	  /** Stripe is configured, so a card can be captured for renewals. */
40	  stripeReady: boolean;
41	  tempSubdomainBase: string;
42	}) {
43	  const [error, setError] = useState("");
44	
45	  async function retry(id: string) {
46	    setError("");
47	    // Surface a rejected retry (e.g. "isn't in a failed state") instead of a silent reload.
48	    const res = await retryHostingProvision(id);
49	    if (res.error) {
50	      setError(res.error);
51	      return;
52	    }
53	    window.location.reload();
54	  }
55	
56	  return (
57	    <div className="space-y-8">
58	      <div>
59	        <h1 className="text-xl font-semibold">Web Hosting</h1>
60	        <p className="mt-1 text-sm text-slate-400">
61	          Host your website without managing a server — we run PHP, databases, email and SSL for you. Start on a free
62	          subdomain or connect your own domain.
63	        </p>
64	      </div>
65	
66	      {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
67	
68	      {/* Your accounts — compact cards linking to the per-account dashboard. */}
69	      {accounts.length > 0 ? (
70	        <div className="space-y-4">
71	          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
72	          <div className="grid gap-3 sm:grid-cols-2">
73	            {accounts.map((a) => (
74	              <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
75	            ))}
76	          </div>
77	        </div>
78	      ) : (
79	        <EmptyState
80	          title="No hosting accounts yet"
81	          sub="Pick a plan below and we’ll set up an isolated hosting account for you — on a free subdomain or your own domain."
82	        />
83	      )}
84	
85	      {/* Order a (new) site — the checkout wizard. */}
86	      <div className="space-y-3">
87	        <h2 className="font-semibold">{accounts.length ? "Host another site" : "Host a new site"}</h2>
88	        {firstMonthFree && plans.length > 0 && (
89	          <div className="flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-300">
90	            <span className="flex h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400 animate-pulse-dot" />
91	            Your first month is free on shared hosting — then the price you sign up at is the price you renew at.
92	          </div>
93	        )}
94	        <HostingDeployWizard
95	          plans={plans}
96	          apps={apps}
97	          annualDiscountPct={annualDiscountPct}
98	          firstMonthFree={firstMonthFree}
99	          balanceCents={balanceCents}
100	          hasCard={hasCard}
101	          cardLabel={cardLabel}
102	          stripeReady={stripeReady}
103	          tempSubdomainBase={tempSubdomainBase}
104	        />
105	      </div>
106	    </div>
107	  );
108	}
109	
110	/* ---------------------------------------------------------------- card --- */
111	
112	function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
113	  const diskGB = Math.round(a.diskQuotaMB / 1024);
114	  const storage = a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`;
115	
116	  const body = (
117	    <>
118	      <div className="flex items-start justify-between gap-2">
119	        <div className="min-w-0">
120	          <p className="truncate font-medium text-slate-100">{a.primaryDomain}</p>
121	          <p className="mt-0.5 text-xs text-slate-500">{a.planName} · PHP {a.phpVersion}</p>
122	        </div>
123	        <StatusDot status={a.status} />
124	      </div>
125	      <div className="mt-3 flex flex-wrap items-center gap-2 text-[11px] text-slate-400">
126	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">Storage {storage}</span>
127	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxSites} extra site{a.maxSites === 1 ? "" : "s"}</span>
128	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxDatabases} DB{a.maxDatabases === 1 ? "" : "s"}</span>
129	        {a.sslActive && <Badge tone="green">HTTPS</Badge>}
130	      </div>
131	    </>
132	  );
133	
134	  // A failed account can't be opened usefully — show the retry affordance inline.
135	  if (a.status === "FAILED") {
136	    return (
137	      <div className="card">
138	        {body}
139	        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
140	          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
141	          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
142	        </div>
143	      </div>
144	    );
145	  }
146	
147	  return (
148	    <Link href={`/dashboard/hosting/${a.id}`} className="card card-hover block transition">
149	      {body}
150	      <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
151	    </Link>
152	  );
153	}
