  },
};

/* ── Decorative server-rack illustration for the hero's top-right. Pure SVG so it
      themes cleanly and needs no asset. To swap in a real render later, replace this
      element with e.g. <img src="/deploy-hero.png" ... /> — nothing else depends on it. */
function ServerRackArt({ className }: { className?: string }) {
  const units = [0, 1, 2, 3, 4];
  return (
    <svg viewBox="0 0 220 260" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden>
      <defs>
        <linearGradient id="rackFace" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#111a30" />
          <stop offset="1" stopColor="#0a101f" />
        </linearGradient>
        <linearGradient id="rackEdge" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#6f47f5" stopOpacity="0.5" />
          <stop offset="1" stopColor="#22d3ee" stopOpacity="0.35" />
        </linearGradient>
      </defs>
      {/* subtle perspective skew via transform */}
      <g transform="skewY(-6)">
        <rect x="24" y="26" width="150" height="220" rx="10" fill="url(#rackFace)" stroke="url(#rackEdge)" strokeWidth="1.5" />
        {units.map((u) => {
          const y = 42 + u * 40;
          const led = u % 2 === 0 ? "#8a70fb" : "#22d3ee";
          return (
            <g key={u}>
              <rect x="34" y={y} width="130" height="30" rx="5" fill="#0d1526" stroke="#253354" strokeWidth="1" />
              {/* vent slits */}
              <rect x="42" y={y + 10} width="54" height="3" rx="1.5" fill="#1a2540" />
              <rect x="42" y={y + 17} width="40" height="3" rx="1.5" fill="#1a2540" />
              {/* status LEDs */}
              <circle cx="150" cy={y + 9} r="3" fill={led}>
                <animate attributeName="opacity" values="0.35;1;0.35" dur={`${2.2 + u * 0.4}s`} repeatCount="indefinite" />
              </circle>
              <circle cx="150" cy={y + 20} r="3" fill="#22d3ee" opacity="0.55" />
            </g>
          );
        })}
      </g>
    </svg>
  );
}

export function DeployHub({
  vps,
  hosting,
  game,
  email,
}: {
  /** null when no active plans/images are configured (VPS deploy unavailable). */
  vps: VpsProps | null;
  hosting: HostingProps;
  /** null when no game families have active tiers. */
  game: GameProps | null;
  email: EmailProps;
}) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const initial = searchParams.get("product");
  const [active, setActive] = useState<DeployProduct>(isProduct(initial) ? initial : "vps");

  const select = useCallback(
    (p: DeployProduct) => {
      setActive(p);
      // Deep-link without a full navigation so the mounted wizard/state is preserved.
      const params = new URLSearchParams(Array.from(searchParams.entries()));
      params.set("product", p);
      router.replace(`/dashboard/deploy?${params.toString()}`, { scroll: false });
    },
    [router, searchParams]
  );

  const activeAccent = ACCENTS[active];

  const wizard = useMemo(() => {
    // Only the ACTIVE product's wizard is ever mounted.
    switch (active) {
      case "vps":
        return vps ? (
          <DeployWizard {...vps} />
        ) : (
          <EmptyState
            title="Deployments are temporarily unavailable"
            sub="No active plans or images are configured. Please check back soon or contact support."
          />
        );
      case "hosting":
        return (
          <div className="space-y-3">
            {/* Display-only promo banner — the charge decision lives in orderHostingAccount.
                Shown only when THIS user is eligible (firstMonthFreeEligible), computed on
                the deploy page exactly as the old hosting page did. */}
            {hosting.firstMonthFree && hosting.plans.length > 0 && (
              <div className="flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-300">
                <span className="flex h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400 animate-pulse-dot" />
                Your first month is free on shared hosting — then the price you sign up at is the price you renew at.
              </div>
            )}
            <HostingDeployWizard {...hosting} />
          </div>
        );
      case "game":
        return game ? (
          <GameDeployWizard {...game} />
        ) : (
          <EmptyState
            title="No game plans available yet"
            sub="Game server plans aren't configured yet. Check back soon, or open a ticket and we'll let you know when they're live."
          />
        );
      case "email":
        return <EmailHosting {...email} />;
    }
  }, [active, vps, hosting, game, email]);

  return (
    <div className="space-y-8">
      {/* ── Hero ─────────────────────────────────────────────────────────────── */}
      <section className="relative overflow-hidden rounded-3xl border border-white/[0.06] bg-navy-900/60 px-6 py-10 sm:px-10 sm:py-12">
        <div aria-hidden className="hero-aura pointer-events-none absolute inset-0" />
        <ServerRackArt
          className="pointer-events-none absolute -right-6 -top-8 hidden h-[280px] w-auto opacity-[0.22] sm:block md:right-4 md:opacity-30"
        />
        <div className="relative max-w-xl">
          <span className="eyebrow-pill mb-4">
            <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Nxeon · Deploy
          </span>
          <h1 className="text-3xl font-black tracking-tight text-white sm:text-4xl">
            <span className="grad-text">Deploy</span> Your Server
          </h1>
          <p className="mt-3 max-w-md text-[15px] leading-relaxed text-slate-400">
            Launch a VPS, shared-hosting site, game server, or business email in minutes.
          </p>
        </div>
      </section>

      {/* ── Product selector: the four cards ARE the tabs ────────────────────── */}
      <div role="tablist" aria-label="Product" className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {PRODUCTS.map((id) => {
          const a = ACCENTS[id];
          const isActive = active === id;
          return (
            <button
              key={id}
              role="tab"
              aria-selected={isActive}
              onClick={() => select(id)}
              className={`card lift group relative flex flex-col items-start text-left transition-all ${
                isActive ? a.activeCard : "hover:border-white/15"
              }`}
            >
              {a.badge && (
                <span className={`absolute right-3 top-3 rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${a.badge.cls}`}>
                  {a.badge.text}
                </span>
              )}
              <span className={`inline-flex h-11 w-11 items-center justify-center rounded-xl bg-gradient-to-br text-white ${a.tile} ${a.tileGlow}`}>
                <a.Icon className="h-5 w-5" />
              </span>
              <span className={`mt-4 text-sm font-semibold ${isActive ? "text-white" : "text-slate-100"}`}>{a.label}</span>
              <span className="mt-1 text-xs leading-relaxed text-slate-400">{a.desc}</span>
              <span className={`mt-3 inline-flex items-center gap-1 text-xs font-medium transition-transform group-hover:translate-x-0.5 ${a.text}`}>
                {isActive ? "Selected" : "Choose"} <span aria-hidden>→</span>
              </span>
            </button>
          );
        })}
      </div>

      {/* ── Active product's wizard ──────────────────────────────────────────── */}
      <div className="border-t border-accent-cyan/0 pt-1">
        <div className="mb-4">
          <h2 className="text-lg font-semibold text-white">{activeAccent.label}</h2>
        </div>
        {wizard}
      </div>
    </div>
  );
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { headers } from "next/headers";
import { capacitySnapshot } from "@/lib/capacity";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { currentPromo } from "@/lib/promotions";
import {
  firstMonthFreeAppliesTo,
  firstMonthFreeEnabled,
  firstMonthFreeEligible,
} from "@/lib/promo-redemption";
import { annualDiscountPct } from "@/lib/annual-discount";
import { taxContextForUser } from "@/lib/tax";
import { defaultTermMonths, getSetting } from "@/lib/settings";
import { GAME_FAMILIES } from "@/lib/games";
import { GAME_CONFIG_SCHEMAS } from "@/lib/game-config";
import { hostingAppCatalog } from "@/worker/hosting";
import { HOSTING_SUBDOMAIN_BASE } from "@/lib/hosting";
import { hasChargeableCard, cardDisplayLabel } from "@/lib/stripe-cards";
import { stripeConfigured } from "@/lib/stripe";
import { clientIp } from "@/lib/rate-limit";
import { hashIp } from "@/lib/coupon-order";
import type { Tier, GameMeta } from "@/components/customer/GameDeployWizard";
import type { PlanOpt, SubscriptionRow } from "@/components/customer/EmailHosting";
import { DeployHub } from "@/components/customer/DeployHub";

export const dynamic = "force-dynamic";

const GAME_META: Record<string, { name: string; glyph: string }> = {
  minecraft: { name: "Minecraft", glyph: "⛏️" },
  valheim: { name: "Valheim", glyph: "🪓" },
  rust: { name: "Rust", glyph: "🔧" },
  palworld: { name: "Palworld", glyph: "🐾" },
  cs2: { name: "Counter-Strike 2", glyph: "🎯" },
  terraria: { name: "Terraria", glyph: "🌳" },
};

export default async function DeployPage() {
  const user = await requireUser();

  /* ── VPS ───────────────────────────────────────────────────────────────────
     Unchanged from the old VPS deploy page — the promo DISPLAY is gated exactly
     as lib/order.ts gates the CHARGE, so displayed === charged. */
  const promo = currentPromo(new Date());
  // The current promo is FIRST-MONTH-FREE (Shared-Hosting only); a VPS order always
  // bills full price, so we must gate the VPS promo DISPLAY the same way orderQuote
  // gates the charge, or the wizard shows "$0 first month" while checkout charges full.
  const vpsPromoApplies = promo.firstMonthFree
    ? firstMonthFreeAppliesTo("VPS") && (await firstMonthFreeEnabled())
    : promo.discountPercent > 0;
  const vpsPromoPercent = vpsPromoApplies ? promo.discountPercent : 0;
  const vpsPromoLabel = vpsPromoApplies ? promo.label : undefined;
  const taxCtx = await taxContextForUser(user);

  const [plans, images, sshKeys, nodes, capacity, freeIps, defaultPlanSlug, defaultTerm] =
    await Promise.all([
      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
      db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
      db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
      db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
      capacitySnapshot(),
      db.dedicatedIp.count({ where: { status: "FREE" } }),
      getSetting("default_plan_slug", ""),
      defaultTermMonths(),
    ]);

  // Resolve slug → id against the same array handed to the wizard (unchanged behaviour).
  const defaultPlanId = defaultPlanSlug ? plans.find((p) => p.slug === defaultPlanSlug)?.id : undefined;

  const [dedIpCents, extraDiskCents, backupPlusCents, annualPct] = await Promise.all([
    dedicatedIpMonthlyCents(),
    extraDiskPerGbCents(),
    backupPlusMonthlyCents(),
    annualDiscountPct(),
  ]);

  const vps =
    plans.length === 0 || images.length === 0
      ? null
      : {
          plans: plans.map((p) => ({
            id: p.id,
            name: p.name,
            cpuCores: p.cpuCores,
            ramMB: p.ramMB,
            diskGB: p.diskGB,
            bandwidthTB: p.bandwidthTB,
            priceCents: p.priceCents,
            storageTier: p.storageTier,
          })),
          images: images.map((o) => ({
            id: o.id,
            slug: o.slug,
            name: o.name,
            category: o.category,
            family: o.family,
            version: o.version,
            logo: o.logo,
            minRamMB: o.minRamMB,
            minDiskGB: o.minDiskGB,
            licenseRequired: o.licenseRequired,
            featured: o.featured,
          })),
          nodes,
          sshKeys: sshKeys.map((k) => ({ id: k.id, name: k.name })),
          isAdmin: user.role === "ADMIN",
          balanceCents: user.balanceCents,
          dedicatedIpAvailable: freeIps > 0,
          dedicatedIpPriceCents: dedIpCents,
          extraDiskPriceCentsPerGb: extraDiskCents,
          backupPlusPriceCents: backupPlusCents,
          defaultPlanId,
          defaultTermMonths: defaultTerm,
          promoPercent: vpsPromoPercent,
          promoLabel: vpsPromoLabel,
          annualDiscountPct: annualPct,
          taxRatePercent: taxCtx.ratePercent,
          taxCountry: taxCtx.country,
        };

  /* ── Shared Hosting ────────────────────────────────────────────────────────
     Fetched identically to the old hosting page. The first-month-free promo is
     HOSTING-ONLY and gated on THIS user's per-user eligibility (userId + ipHash),
     the same predicate orderHostingAccount charges on — NOT the global toggle. */
  const [hostingPlans, hostingPromoOn] = await Promise.all([
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    firstMonthFreeAppliesTo("HOSTING") ? firstMonthFreeEnabled() : Promise.resolve(false),
  ]);
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  const hostingFirstMonthFree = hostingPromoOn && (await firstMonthFreeEligible(user.id, ipHash));
  const hasCard = hasChargeableCard(user);
  const cardLabel = hasCard
    ? cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear })
    : null;
  const hosting = {
    plans: hostingPlans.map((p) => ({
      id: p.id,
      name: p.name,
      priceCents: p.priceCents,
      diskGB: p.diskGB,
      maxSites: p.maxSites,
      maxDatabases: p.maxDatabases,
      bandwidthTB: p.bandwidthTB,
      mailboxes: p.mailboxes,
      freeMigration: p.freeMigration,
      featured: p.featured,
      tagline: p.tagline,
    })),
    apps: hostingAppCatalog(),
    annualDiscountPct: annualPct,
    firstMonthFree: hostingFirstMonthFree,
    balanceCents: user.balanceCents,
    hasCard,
    cardLabel,
    stripeReady: stripeConfigured(),
    tempSubdomainBase: HOSTING_SUBDOMAIN_BASE,
  };

  /* ── Game Servers ─────────────────────────────────────────────────────────── */
  const gamePlans = await db.gamePlan.findMany({
    where: { active: true },
    orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
  });
  const tiers: Tier[] = gamePlans.map((g) => ({
    id: g.id,
    gameFamily: g.gameFamily,
    name: g.name,
    ramMB: g.ramMB,
    cpuCores: g.cpuCores,
    diskGB: g.diskGB,
    slots: g.slots,
    priceCents: g.priceCents,
    termMonths: g.termMonths,
    featured: g.featured,
  }));
  const withTiers = new Set(tiers.map((t) => t.gameFamily));
  const gameMeta: GameMeta[] = GAME_FAMILIES.filter((f) => withTiers.has(f)).map((f) => ({
    family: f,
    name: GAME_META[f]?.name ?? f,
    glyph: GAME_META[f]?.glyph ?? "🎮",
  }));
  const game =
    gameMeta.length === 0
      ? null
      : {
          games: gameMeta,
          tiers,
          balanceCents: user.balanceCents,
          annualDiscountPct: annualPct,
          schemas: GAME_CONFIG_SCHEMAS,
          stripeConfigured: stripeConfigured(),
        };

  /* ── Business Email ────────────────────────────────────────────────────────
     Same data the /dashboard/email page feeds the order flow. */
  const [emailDomains, emailPlans, emailSubs] = await Promise.all([
    db.domain.findMany({ where: { userId: user.id, status: "ACTIVE" }, orderBy: { name: "asc" } }),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.emailSubscription.findMany({
      where: { userId: user.id, status: { not: "CANCELLED" } },
      include: { emailPlan: true, mailboxes: { orderBy: { createdAt: "asc" } } },
      orderBy: { createdAt: "desc" },
    }),
  ]);
  const emailPlanOpts: PlanOpt[] = emailPlans.map((p) => ({
    id: p.id,
    name: p.name,
    mailboxes: p.mailboxes,
    storageGB: p.storageGB,
    priceCents: p.priceCents,
    termMonths: p.termMonths,
  }));
  const emailSubRows: SubscriptionRow[] = emailSubs.map((s) => ({
    id: s.id,
    domainName: s.domainName,
    status: s.status,
    external: s.external,
    verified: s.verified,
    planName: s.emailPlan.name,
    planMailboxes: s.emailPlan.mailboxes,
    planStorageGB: s.emailPlan.storageGB,
    expiresAt: s.expiresAt ? s.expiresAt.toISOString() : null,
    mailboxes: s.mailboxes.map((m) => ({
      id: m.id,
      address: m.address,
      status: m.status,
      createdAt: m.createdAt.toISOString(),
    })),
  }));
  const email = {
    domains: emailDomains.map((d) => d.name),
    plans: emailPlanOpts,
    subscriptions: emailSubRows,
    balanceCents: user.balanceCents,
    annualDiscountPct: annualPct,
  };

  return (
    <div className="space-y-6">
      {capacity.nearCapacity && (
        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
          <span className="font-semibold">Host is filling up.</span> We&apos;re at{" "}
          {Math.round(capacity.ramUtilization * 100)}% of committed RAM. Larger plans may be briefly unavailable.
        </div>
      )}
      <DeployHub vps={vps} hosting={hosting} game={game} email={email} />
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { retryHostingProvision, type HostingAccountView } from "@/lib/actions-hosting";
import { Badge, EmptyState, StatusDot } from "@/components/ui/primitives";

export function HostingClient({
  accounts,
}: {
  accounts: HostingAccountView[];
}) {
  const [error, setError] = useState("");

  async function retry(id: string) {
    setError("");
    // Surface a rejected retry (e.g. "isn't in a failed state") instead of a silent reload.
    const res = await retryHostingProvision(id);
    if (res.error) {
      setError(res.error);
      return;
    }
    window.location.reload();
  }

  return (
    <div className="space-y-8">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h1 className="text-xl font-semibold">Web Hosting</h1>
          <p className="mt-1 max-w-2xl text-sm text-slate-400">
            Host your website without managing a server — we run PHP, databases, email and SSL for you. Start on a free
            subdomain or connect your own domain.
          </p>
        </div>
        {accounts.length > 0 && (
          <Link href="/dashboard/deploy?product=hosting" className="btn-primary shrink-0">
            Deploy new site →
          </Link>
        )}
      </div>

      {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}

      {/* Your accounts — compact cards linking to the per-account dashboard. */}
      {accounts.length > 0 ? (
        <div className="space-y-4">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            {accounts.map((a) => (
              <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
            ))}
          </div>
        </div>
      ) : (
        <EmptyState
          title="No hosting accounts yet"
          sub="Set up an isolated hosting account — on a free subdomain or your own domain — in a couple of minutes."
          action={
            <Link href="/dashboard/deploy?product=hosting" className="btn-primary">
              Deploy your first site →
            </Link>
          }
        />
      )}
    </div>
  );
}

/* ---------------------------------------------------------------- card --- */

function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
  const diskGB = Math.round(a.diskQuotaMB / 1024);
  const storage = a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`;

  const body = (
    <>
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="truncate font-medium text-slate-100">{a.primaryDomain}</p>
          <p className="mt-0.5 text-xs text-slate-500">{a.planName} · PHP {a.phpVersion}</p>
        </div>
        <StatusDot status={a.status} />
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-2 text-[11px] text-slate-400">
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">Storage {storage}</span>
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxSites} extra site{a.maxSites === 1 ? "" : "s"}</span>
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxDatabases} DB{a.maxDatabases === 1 ? "" : "s"}</span>
        {a.sslActive && <Badge tone="green">HTTPS</Badge>}
      </div>
    </>
  );

  // A failed account can't be opened usefully — show the retry affordance inline.
  if (a.status === "FAILED") {
    return (
      <div className="card">
        {body}
        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
        </div>
      </div>
    );
  }

  return (
    <Link href={`/dashboard/hosting/${a.id}`} className="card card-hover block transition">
      {body}
      <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
    </Link>
  );
}

import { requireUser } from "@/lib/auth";
import { listHostingAccounts } from "@/lib/actions-hosting";
import { HostingClient } from "@/components/customer/HostingClient";

export const dynamic = "force-dynamic";

// Manage-existing view only. The order/checkout wizard now lives solely on
// /dashboard/deploy?product=hosting (the unified Deploy hub) — a single source of
// truth for the money-audited HostingDeployWizard. This page lists + manages the
// customer's existing accounts and links to the hub to deploy new sites.
export default async function HostingPage() {
  await requireUser();
  const accounts = await listHostingAccounts();
  return <HostingClient accounts={accounts} />;
}

