import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PageHeader, EmptyState, StatusDot } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";

const GAME_META: Record<string, { name: string; glyph: string }> = {
  minecraft: { name: "Minecraft", glyph: "⛏️" },
  valheim: { name: "Valheim", glyph: "🪓" },
  rust: { name: "Rust", glyph: "🔧" },
  palworld: { name: "Palworld", glyph: "🐾" },
  cs2: { name: "Counter-Strike 2", glyph: "🎯" },
  terraria: { name: "Terraria", glyph: "🌳" },
};

// Manage-existing view only. The deploy/checkout wizard (GameDeployWizard) now lives
// solely on /dashboard/deploy?product=game — a single source of truth for the
// money-audited flow. This page lists + manages the customer's existing game servers.
export default async function DashboardGamesPage() {
  const user = await requireUser();

  const servers = await db.server.findMany({
    where: { userId: user.id, gamePlanId: { not: null } },
    include: { plan: true, osTemplate: true, gamePlan: true },
    orderBy: { createdAt: "desc" },
  });

  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PageHeader
        title="Game servers"
        sub="Your ready-to-play game servers — sized and priced per game."
      >
        <Link href="/dashboard/deploy?product=game" className="btn-primary">
          + Deploy new game server →
        </Link>
      </PageHeader>

      {servers.length === 0 ? (
        <EmptyState
          title="No game servers yet"
          sub="Spin up a ready-to-play Minecraft, Rust, Valheim or Palworld server in minutes."
          action={
            <Link href="/dashboard/deploy?product=game" className="btn-primary">
              Deploy your first game server →
            </Link>
          }
        />
      ) : (
        <div className="grid gap-3 sm:grid-cols-2">
          {servers.map((s) => {
            const family = s.osTemplate.family;
            const meta = GAME_META[family] ?? { name: family, glyph: "🎮" };
            return (
              <Link
                key={s.id}
                href={`/dashboard/servers/${s.id}`}
                className="card card-hover block transition"
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="flex min-w-0 items-center gap-3">
                    <span className="text-2xl leading-none" aria-hidden>{meta.glyph}</span>
                    <div className="min-w-0">
                      <p className="truncate font-medium text-slate-100">{s.hostname}</p>
                      <p className="mt-0.5 text-xs text-slate-500">
                        {meta.name}
                        {s.gamePlan ? ` · ${s.gamePlan.name}` : ""}
                        {s.gamePlan?.slots ? ` · ${s.gamePlan.slots} slots` : ""}
                      </p>
                    </div>
                  </div>
                  <StatusDot status={s.status} />
                </div>
                <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

